{"success": true, "data": {"stdout": "# Stratified BM25 overlap analysis: compares BM25 top-k negatives against
# other mining strategies (random, embedding_distance, dataflow_aware),
# stratified by repo size (unique file count).
#
# Input:  /root/autodl-tmp/structfuse/full_m2_training_data/train_{strategy}_s42.jsonl
# Output: /root/autodl-tmp/structfuse/artifacts/bm25_overlap_stratified.json

import json
import os
from collections import defaultdict

import numpy as np

DATA_DIR = "/root/autodl-tmp/structfuse/full_m2_training_data"
OUT_PATH = "/root/autodl-tmp/structfuse/artifacts/bm25_overlap_stratified.json"
STRATEGIES = ["random", "embedding_distance", "dataflow_aware"]
SEED = 42
K = 7
TIERS = {
    "small_lt50": (0, 50),
    "medium_50_200": (50, 201),
    "large_200plus": (201, float("inf")),
}


def extract_repo(query_id: str) -> str:
    iid = query_id.split("::")[0]
    return iid.split(".")[0]


def extract_filepath(full_id: str) -> str:
    return full_id.split("::", 1)[1]


def jaccard(a: set, b: set) -> float:
    if not a and not b:
        return 1.0
    union = a | b
    if not union:
        return 0.0
    return len(a & b) / len(union)


def load_strategy(name: str) -> dict:
    path = os.path.join(DATA_DIR, f"train_{name}_s{SEED}.jsonl")
    data = {}
    with open(path) as f:
        for line in f:
            d = json.loads(line)
            data[d["query_id"]] = d["neg_candidates"]
    return data


def main():
    # 1. Load all strategies
    bm25_data = load_strategy("bm25")
    other_data = {s: load_strategy(s) for s in STRATEGIES}

    # 2. Build repo file count (union of all file paths across all strategies)
    repo_files = defaultdict(set)
    for qid, negs in bm25_data.items():
        repo = extract_repo(qid)
        repo_files[repo].add(extract_filepath(qid))
        for nc in negs:
            repo_files[repo].add(extract_filepath(nc))
    for strat in STRATEGIES:
        for qid, negs in other_data[strat].items():
            repo = extract_repo(qid)
            repo_files[repo].add(extract_filepath(qid))
            for nc in negs:
                repo_files[repo].add(extract_filepath(nc))

    repo_size = {repo: len(files) for repo, files in repo_files.items()}

    # 3. Compute per-query overlaps (only for queries present in both BM25 and other)
    records = []  # list of dicts with overlap info per query
    for qid, bm25_negs in bm25_data.items():
        repo = extract_repo(qid)
        rsize = repo_size.get(repo, 0)
        bm25_topk = set(bm25_negs[:K])

        row = {
            "query_id": qid,
            "repo": repo,
            "repo_size": rsize,
            "bm25_pool_size": len(bm25_negs),
        }
        for strat in STRATEGIES:
            if qid in other_data[strat]:
                other_topk = set(other_data[strat][qid][:K])
                row[f"overlap_{strat}"] = jaccard(bm25_topk, other_topk)
            else:
                row[f"overlap_{strat}"] = None
        records.append(row)

    # 4. Stratify and compute stats
    def compute_tier_stats(tier_records):
        repos_in_tier = set(r["repo"] for r in tier_records)
        stats = {
            "repo_count": len(repos_in_tier),
            "instance_count": len(tier_records),
        }
        for strat in STRATEGIES:
            key = f"overlap_{strat}"
            vals = [r[key] for r in tier_records if r[key] is not None]
            if vals:
                arr = np.array(vals)
                stats[f"avg_overlap_bm25_{strat.replace('embedding_distance','embedding')}"] = round(float(arr.mean()), 4)
                stats[f"median_overlap_bm25_{strat.replace('embedding_distance','embedding')}"] = round(float(np.median(arr)), 4)
                stats[f"matched_queries_{strat.replace('embedding_distance','embedding')}"] = len(vals)
            else:
                stats[f"avg_overlap_bm25_{strat.replace('embedding_distance','embedding')}"] = None
                stats[f"median_overlap_bm25_{strat.replace('embedding_distance','embedding')}"] = None
                stats[f"matched_queries_{strat.replace('embedding_distance','embedding')}"] = 0
        return stats

    result = {
        "overall": compute_tier_stats(records),
        "seed": f"s{SEED} only",
        "k": K,
        "repo_size_method": "union of unique file paths across all strategies",
    }

    for tier_name, (lo, hi) in TIERS.items():
        tier_records = [r for r in records if lo <= r["repo_size"] < hi]
        result[tier_name] = compute_tier_stats(tier_records)
        # Add repo size stats for this tier
        sizes = [r["repo_size"] for r in tier_records]
        if sizes:
            result[tier_name]["avg_repo_size"] = round(float(np.mean(sizes)), 1)
            result[tier_name]["min_repo_size"] = int(min(sizes))
            result[tier_name]["max_repo_size"] = int(max(sizes))

    # Add per-tier BM25 pool size stats (how many BM25 candidates available)
    for tier_name, (lo, hi) in TIERS.items():
        tier_records = [r for r in records if lo <= r["repo_size"] < hi]
        pools = [r["bm25_pool_size"] for r in tier_records]
        if pools:
            result[tier_name]["avg_bm25_pool_size"] = round(float(np.mean(pools)), 1)

    os.makedirs(os.path.dirname(OUT_PATH), exist_ok=True)
    with open(OUT_PATH, "w") as f:
        json.dump(result, f, indent=2, ensure_ascii=False)

    print(json.dumps(result, indent=2, ensure_ascii=False))


if __name__ == "__main__":
    main()
